"""Refresh v3 evidence counts/anchors from validated local maps, without changing rules."""
import sys,collections
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from physstyle.common import *
root=Path('skills/physics-paper-style-v3');sem=read_json('reports/structure_semantic_results.json');stage=read_json('reports/STRUCTURE_RESULTS.json');anchors=read_jsonl('data/structure/source_anchors.jsonl')
examples=[('G1','1602.05065','c7','An initially motivated viability question can end in a negative conclusion.'),('G1','1909.00580','l1','An observational fit alone does not establish the proposed mechanism.'),('G2','1004.3611','c1','The linear alignment branch has a restricted rescaling result.'),('G2','1004.3611','c2','The quadratic branch has a different distinguishability result.'),('G3','1405.2215','c3','A result is previewed, developed under its energy bound and later recapped.'),('G3','2007.04256','ev1','A robustness argument follows use of an approximation; this is not automatically an ordering defect.'),('G4','1007.0970','c6','A final interpretation can occur without a separate conclusion section.'),('G4','1004.3611','c5','A discussion can still contain a new mitigation calculation.')]
selected=[]
for rule,pid,node,note in examples:
 candidates=[a for a in anchors if a['paper_id']==pid and a['node_id']==node]
 if not candidates:raise ValueError('missing selected anchor '+pid+node)
 # At most two located occurrences illustrate function, not a full text export.
 for a in candidates[:2]:selected.append({'rule':rule,'organizational_observation':note,**a})
for item in selected:
 item['exact_quote_sha256']=digest(item.pop('exact_quote').encode())
 item['quote_policy']='Exact fragment remains in local data/structure/source_anchors.jsonl; portable index carries paraphrase, hash and source location only.'
write_jsonl(root/'references/structure-source-anchors.jsonl',selected)
lines=['# Whole-paper evidence and limits','',f'The current validated semantic inventory contains {sem["papers_full_mainbody_read"]} discovery papers, {sem["main_paragraphs"]} parsed main-body paragraphs and {sem["main_prose_words"]} prose words actually read, with {sem["selected_nodes"]} selected nodes and {sem["selected_edges"]} selected edges. Figures, appendices and parser-boundary limitations are recorded individually in the project report. These are host-agent judgments, not human gold labels.','',f'Initial selection:12 papers, one per three categories × four year bands,800–12000parsedprosewords, prior local-window papers excluded. A second12-paper stage uses the second rank under the same seed/eligibility per stratum, selected after initial auditing; this is further discovery, not heldout confirmation. A subsequent6-paper newly acquired cohort is listed separately in profile.json. Selected graph nodes and recurrence pairs are not exhaustive; they cannot estimate whole-corpus prevalence.','',f'Among these maps, {sem["papers_with_claim_preview_and_development"]} papers have at least one selected claim with both preview and development occurrences. Question states: {sem["question_status_counts"]}; edge evidential bases: {sem["edge_basis_counts"]}. These describe annotations, not readability benefits.','', '| Candidate operation | Source-located observation | Inference boundary |','|---|---|---|']
for rule,pid,node,note in examples:lines.append(f'| {rule} | {pid}, node {node}: {note} | An observed option/counterexample; no causal benefit established. |')
lines+=['','Read [structure-source-anchors.jsonl](structure-source-anchors.jsonl) for exact versions, hashes, paragraphs and raw source-line containers. Underlying exact fragments were checked against comment-stripped raw source and remain in the local evidence cache; the portable index contains organizational paraphrases and quote hashes. Container line spans are not exact token-level coordinates. The paper authors’ scientific claims are not independently endorsed.','', 'G1–G4 are engineering hypotheses derived from these observations and argument-traceability requirements. In particular, allocating explanatory space and choosing an appendix are design judgments; no historical frequency proves the optimal placement. There is no prescribed section count, relative length or dependency-order score.','', 'Automatic corpus measurements only supply section/label/reference navigation and frozen D01–D06 distributions. They cannot extract logical support by themselves. The learned distinction is between presentation order and logical dependence: a preview may legitimately precede the support required to assess it.','', 'Independent source review and writing-task validation are documented in the project release report. Even successful execution does not demonstrate reader preference. Existing v1/v2 blind-study outputs remain frozen and cannot establish a v3 effect.']
(root/'references/structure-evidence.md').write_text('\n'.join(lines)+'\n')
profile={'status':'candidate; no human readability benefit established','version':3,'corpus_papers':stage['papers_usable'] if stage else 210,'discovery_papers':stage['split_counts']['discovery'] if stage else 168,'heldout_papers':stage['split_counts']['heldout'] if stage else 42,'automatic_feature_scope':'D01–D06 and source-located navigation inventory; not automatic argument inference','local_semantic':{'original':{'papers':15,'windows':60,'labels':360},'v2_additional':{'papers':12,'windows':60,'labels':360},'pooling':'separate designs and denominators; inventory total27papers/120windows/720labels'},'structure_semantic':{k:sem[k] for k in ['papers_full_mainbody_read','main_paragraphs','main_prose_words','selected_nodes','selected_edges','edge_basis_counts','question_status_counts','sampling_stages']},'structure_sample_files':['data/structure/sample.json']+(['data/structure/additional_sample.json'] if Path('data/structure/additional_sample.json').exists() else [])+(['data/structure/supplement_sample.json'] if Path('data/structure/supplement_sample.json').exists() else []),'new_exploratory_feature_groups':['M01','M02','M03','M04'],'structural_anchor_count':len(selected),'structural_anchor_sha256':digest((root/'references/structure-source-anchors.jsonl').read_bytes()),'candidate_operations':7,'human_readability_effect':'not_established','weights_trained':False}
if stage:profile['reference_distributions']=read_json(stage['profile_file'])['discovery']
write_json(root/'profile.json',profile)
print('v3 evidence refreshed:',profile['corpus_papers'],'corpus /',sem['papers_full_mainbody_read'],'whole-paper maps')
